// BRBI CIMS Phase 2A-7, Workflow B "Select Deliverable": decide per subject from ALL of its rows
// (input: every row of every subject that has a due row; rows may repeat and are de-duplicated).
//  - Only the highest schedule_version is authoritative; a lower-version duplicate is ignored.
//  - If the authoritative version is cancelled, nothing is sent.
//  - "sent" and "uncertain" are never retried automatically.
//  - "failed" (a definitive provider rejection) is retried at most MAX_ATTEMPTS times.
//  - A "sending" claim older than STALE_CLAIM_MINUTES has an unknown outcome -> "uncertain".
const MAX_ATTEMPTS = 3;
const STALE_CLAIM_MINUTES = 30;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const now = Date.now();
const runToken = `${$execution.id}:${now}`;

const bySubject = new Map();
const seen = new Set();
for (const item of $input.all()) {
    const row = item.json;
    if (!row || typeof row.subject_key !== 'string' || seen.has(String(row.id))) {
        continue;
    }
    seen.add(String(row.id));
    if (!bySubject.has(row.subject_key)) {
        bySubject.set(row.subject_key, []);
    }
    bySubject.get(row.subject_key).push(row);
}

const output = [];
for (const [subjectKey, rows] of bySubject) {
    const version = Math.max(...rows.map((row) => Number(row.schedule_version)));
    const current = rows.filter((row) => Number(row.schedule_version) === version);
    if (current.some((row) => row.status !== 'scheduled')) {
        continue;
    }

    const states = current.map((row) => row.delivery_status);
    if (states.includes('sent') || states.includes('uncertain') || states.includes('skipped')) {
        continue;
    }

    const row = current[0];
    if (!(Date.parse(row.trigger_at_utc) <= now)) {
        continue;
    }

    const common = {
        subject_key: subjectKey,
        schedule_version: version,
        event_id: row.last_event_id,
        recipient_user_id: Number(row.recipient_user_id),
        delivery_key: `${subjectKey}:v${version}`,
    };

    const sending = current.find((candidate) => candidate.delivery_status === 'sending');
    if (sending) {
        if (now - Date.parse(sending.delivery_updated_at) > STALE_CLAIM_MINUTES * 60 * 1000) {
            output.push({
                json: {
                    ...common,
                    action: 'record',
                    claim_token: sending.delivery_claim,
                    outcome: 'uncertain',
                    next_claim: sending.delivery_claim,
                    next_attempt_at: null,
                    attempt_number: Number(sending.delivery_attempts) || 0,
                    provider_message_id: '',
                    response_status: null,
                    error_code: 'claim_expired_without_result',
                    attempted_at: new Date(now).toISOString(),
                },
            });
        }
        continue;
    }

    if (typeof row.recipient_email !== 'string' || !EMAIL.test(row.recipient_email)) {
        continue;
    }

    const attempts = Number(row.delivery_attempts) || 0;
    const retryDue = row.delivery_status === 'failed'
        && attempts < MAX_ATTEMPTS
        && (row.delivery_next_attempt_at === null || row.delivery_next_attempt_at === '' || Date.parse(row.delivery_next_attempt_at) <= now);
    if (row.delivery_status !== 'pending' && !retryDue) {
        continue;
    }

    output.push({
        json: {
            ...common,
            action: 'claim',
            claim_token: `${runToken}:${subjectKey}`,
            expected_delivery_status: row.delivery_status,
            expected_attempts: attempts,
            attempt_number: attempts + 1,
            recipient_email: row.recipient_email,
            subject_label: row.subject_label,
            activities_url: row.activities_url,
            trigger_at_manila: row.trigger_at_manila,
            has_specific_time: row.has_specific_time === true,
        },
    });
}

return output;

// BRBI CIMS Phase 2A-7, Workflow B "Confirm Claims": keep only candidates whose claim this execution now owns.
// The claim itself was one guarded UPDATE (status, version, delivery state and attempt count must
// all still match), so of two overlapping executions at most one can own a subject's claim.
const candidates = $('Select Deliverable').all().map((item) => item.json).filter((candidate) => candidate.action === 'claim');
const rows = $input.all().map((item) => item.json).filter((row) => row && typeof row.subject_key === 'string');

function when(candidate) {
    const date = String(candidate.trigger_at_manila).slice(0, 10);
    const time = String(candidate.trigger_at_manila).slice(11, 16);

    return candidate.has_specific_time ? `${date} ${time} (Asia/Manila)` : `${date} (Asia/Manila)`;
}

const output = [];
for (const candidate of candidates) {
    const owned = rows.some((row) => row.subject_key === candidate.subject_key
        && Number(row.schedule_version) === candidate.schedule_version
        && row.delivery_claim === candidate.claim_token);
    if (!owned) {
        continue;
    }

    // Generic wording only: subject_label is a generic activity label chosen by Laravel.
    output.push({
        json: {
            ...candidate,
            email_subject: `BRBI CIMS reminder: ${candidate.subject_label} scheduled ${when(candidate)}`,
            email_body: [
                'This is a reminder for a CI activity you created in BRBI CIMS.',
                '',
                `Activity: ${candidate.subject_label}`,
                `Scheduled: ${when(candidate)}`,
                '',
                `Open the activities list: ${candidate.activities_url}`,
                '',
                'This message was sent automatically. Sign in to BRBI CIMS for details.',
            ].join('\n'),
        },
    });
}

return output;

// BRBI CIMS Phase 2A-7, Workflow B "Interpret Gmail Outcome" (run once for each item).
// Connected to BOTH Gmail outputs: an item carrying `error` came from the error output.
//
//  - "sent" only for a recognisable Gmail API message resource (id, threadId, labelIds incl. SENT).
//    Anything else on the success output, including the pass-through item a DISABLED Gmail node
//    emits, is "uncertain".
//  - A definite 4xx rejection (except 408) means Gmail did not accept the message: "failed",
//    retried at most MAX_ATTEMPTS times after a growing delay.
//  - 5xx, 408, timeouts, network resets and unknown errors may or may not have sent the
//    message: "uncertain", NEVER retried automatically.
const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MINUTES = 15;
const claim = $('Confirm Claims').item.json;
const now = Date.now();

let outcome;
let status = null;
let providerMessageId = '';
let errorCode = '';
let nextAttemptAt = null;

if ($json && $json.error) {
    const error = $json.error;
    const fromMessage = String(error.message || error.description || '').match(/\b([45]\d\d)\b/);
    status = [error.httpCode, error.status, error.statusCode, fromMessage ? fromMessage[1] : null]
        .map(Number)
        .find((value) => Number.isInteger(value) && value >= 100 && value <= 599) ?? null;
    const definite = status !== null && status >= 400 && status < 500 && status !== 408;
    outcome = definite ? 'failed' : 'uncertain';
    errorCode = definite ? `gmail_rejected_${status}` : 'gmail_outcome_uncertain';
    if (definite && claim.attempt_number < MAX_ATTEMPTS) {
        nextAttemptAt = new Date(now + RETRY_DELAY_MINUTES * claim.attempt_number * 60 * 1000).toISOString();
    }
} else {
    const sent = $json
        && typeof $json.id === 'string'
        && typeof $json.threadId === 'string'
        && Array.isArray($json.labelIds)
        && $json.labelIds.includes('SENT');
    outcome = sent ? 'sent' : 'uncertain';
    providerMessageId = sent ? $json.id : '';
    errorCode = sent ? '' : 'gmail_response_unrecognized';
}

return {
    json: {
        action: 'record',
        subject_key: claim.subject_key,
        schedule_version: claim.schedule_version,
        event_id: claim.event_id,
        recipient_user_id: claim.recipient_user_id,
        delivery_key: claim.delivery_key,
        claim_token: claim.claim_token,
        outcome,
        // A failed attempt releases the claim so a later run may retry it.
        next_claim: outcome === 'failed' ? '' : claim.claim_token,
        next_attempt_at: nextAttemptAt,
        attempt_number: claim.attempt_number,
        provider_message_id: providerMessageId,
        response_status: status,
        error_code: errorCode,
        attempted_at: new Date(now).toISOString(),
    },
};
